--
-- Table structure for table `privacy_settings`
--

DROP TABLE IF EXISTS `privacy_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `privacy_settings` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '璁剧疆ID',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `profile_visibility` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'public' COMMENT '涓?汉淇℃伅鍙??鎬э細public-鍏?紑锛宲rivate-绉佸瘑',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  CONSTRAINT `fk_privacy_user` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='闅愮?璁剧疆琛';
/*!40101 SET character_set_client = @saved_cs_client */;

