--
-- Table structure for table `tb_order_item`
--

DROP TABLE IF EXISTS `tb_order_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_order_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '璁㈠崟椤笽D',
  `order_id` bigint NOT NULL COMMENT '璁㈠崟ID',
  `product_id` bigint NOT NULL COMMENT '鍟嗗搧ID',
  `product_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍟嗗搧鍚嶇О锛堝揩鐓э級',
  `product_price` decimal(10,2) NOT NULL COMMENT '鍟嗗搧鍗曚环锛堝揩鐓э級',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '璐?拱鏁伴噺',
  `total_price` decimal(10,2) NOT NULL COMMENT '灏忚?閲戦?',
  `product_image` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍟嗗搧鍥剧墖锛堝揩鐓э級',
  `seller_id` bigint NOT NULL COMMENT '鍗栧?ID',
  `seller_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍗栧?鐢ㄦ埛鍚',
  `ship_status` tinyint DEFAULT '0',
  `ship_time` datetime DEFAULT NULL COMMENT '鍙戣揣鏃堕棿',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_order_item_order` (`order_id`),
  KEY `idx_order_item_product` (`product_id`),
  KEY `idx_order_item_seller` (`seller_id`),
  CONSTRAINT `fk_order_item_order` FOREIGN KEY (`order_id`) REFERENCES `tb_order` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_order_item_product` FOREIGN KEY (`product_id`) REFERENCES `tb_product` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_order_item_seller` FOREIGN KEY (`seller_id`) REFERENCES `tb_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2083 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='璁㈠崟椤硅〃';
/*!40101 SET character_set_client = @saved_cs_client */;

