DROP TABLE IF EXISTS `tb_price_alert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_price_alert` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鎻愰啋ID',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `product_id` bigint NOT NULL COMMENT '鍟嗗搧ID',
  `target_price` decimal(10,2) NOT NULL COMMENT '鐩?爣浠锋牸',
  `current_price` decimal(10,2) NOT NULL COMMENT '璁剧疆鏃剁殑褰撳墠浠锋牸',
  `status` int NOT NULL,
  `triggered_time` datetime DEFAULT NULL COMMENT '瑙﹀彂鏃堕棿',
  `triggered_price` decimal(10,2) DEFAULT NULL COMMENT '瑙﹀彂鏃剁殑浠锋牸',
  `notified` bit(1) DEFAULT NULL,
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_product` (`user_id`,`product_id`),
  KEY `idx_price_alert_user` (`user_id`),
  KEY `idx_price_alert_product` (`product_id`),
  KEY `idx_price_alert_status` (`status`),
  CONSTRAINT `fk_price_alert_product` FOREIGN KEY (`product_id`) REFERENCES `tb_product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_price_alert_user` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='闄嶄环鎻愰啋琛';
/*!40101 SET character_set_client = @saved_cs_client */;

