DROP TABLE IF EXISTS `tb_price_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_price_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '璁板綍ID',
  `product_id` bigint NOT NULL COMMENT '鍟嗗搧ID',
  `price` decimal(10,2) NOT NULL COMMENT '璁板綍鏃剁殑浠锋牸',
  `original_price` decimal(10,2) DEFAULT NULL COMMENT '鍘熶环',
  `recorded_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '璁板綍鏃堕棿',
  `change_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍙樺寲绫诲瀷锛欼NITIAL-鍒濆?锛孖NCREASE-娑ㄤ环锛孌ECREASE-闄嶄环锛孶NCHANGED-涓嶅彉',
  `change_amount` decimal(10,2) DEFAULT NULL COMMENT '浠锋牸鍙樺寲閲戦?',
  `change_rate` decimal(5,2) DEFAULT NULL COMMENT '浠锋牸鍙樺寲鐧惧垎姣',
  PRIMARY KEY (`id`),
  KEY `idx_price_history_product` (`product_id`),
  KEY `idx_price_history_time` (`recorded_time`),
  CONSTRAINT `fk_price_history_product` FOREIGN KEY (`product_id`) REFERENCES `tb_product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1041 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='浠锋牸鍘嗗彶琛';
