--
-- Table structure for table `tb_product`
--

DROP TABLE IF EXISTS `tb_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_product` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鍟嗗搧ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍟嗗搧鍚嶇О',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '鍟嗗搧鎻忚堪',
  `category_id` bigint NOT NULL COMMENT '鍒嗙被ID',
  `price` decimal(10,2) NOT NULL COMMENT '鍟嗗搧浠锋牸',
  `original_price` decimal(10,2) DEFAULT NULL COMMENT '鍘熶环',
  `pending_price` decimal(10,2) DEFAULT NULL COMMENT '寰呭?鏍镐环鏍',
  `pending_original_price` decimal(10,2) DEFAULT NULL COMMENT '寰呭?鏍稿師浠',
  `stock` int NOT NULL DEFAULT '0' COMMENT '搴撳瓨鏁伴噺',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '涔愯?閿佺増鏈?彿',
  `sales` int NOT NULL DEFAULT '0' COMMENT '閿?噺',
  `status` tinyint NOT NULL DEFAULT '1',
  `main_image` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '涓诲浘URL',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '鍟嗗搧鍥剧墖鍒楄〃锛圝SON鏍煎紡锛',
  `seller_id` bigint NOT NULL COMMENT '鍗栧?鐢ㄦ埛ID',
  `seller_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍗栧?鐢ㄦ埛鍚',
  `audit_status` tinyint NOT NULL DEFAULT '1',
  `audit_remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '瀹℃牳澶囨敞',
  `audit_time` datetime DEFAULT NULL COMMENT '瀹℃牳鏃堕棿',
  `ad_video` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '骞垮憡瑙嗛?URL',
  `ad_video_duration` int DEFAULT NULL COMMENT '骞垮憡鏃堕暱(绉?',
  `ad_video_enabled` tinyint DEFAULT '0',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_product_category` (`category_id`),
  KEY `idx_product_status` (`status`),
  KEY `idx_product_name` (`name`),
  KEY `idx_product_audit` (`audit_status`),
  KEY `idx_product_seller` (`seller_id`),
  CONSTRAINT `fk_product_category` FOREIGN KEY (`category_id`) REFERENCES `tb_category` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_product_seller` FOREIGN KEY (`seller_id`) REFERENCES `tb_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=131 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='鍟嗗搧琛';
/*!40101 SET character_set_client = @saved_cs_client */;

