--
-- Table structure for table `tb_review`
--

DROP TABLE IF EXISTS `tb_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_review` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '璇勪环ID',
  `product_id` bigint NOT NULL COMMENT '鍟嗗搧ID',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `order_id` bigint NOT NULL COMMENT '璁㈠崟ID',
  `order_item_id` bigint DEFAULT NULL COMMENT '璁㈠崟椤笽D',
  `rating` int NOT NULL COMMENT '璇勫垎1-5鏄',
  `content` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '璇勪环鍐呭?',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '璇勪环鍥剧墖锛圝SON鏁扮粍锛',
  `is_anonymous` bit(1) NOT NULL,
  `reply` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍟嗗?鍥炲?',
  `reply_time` datetime DEFAULT NULL COMMENT '鍥炲?鏃堕棿',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_review_product` (`product_id`),
  KEY `idx_review_user` (`user_id`),
  KEY `idx_review_order` (`order_id`),
  CONSTRAINT `fk_review_order` FOREIGN KEY (`order_id`) REFERENCES `tb_order` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_review_product` FOREIGN KEY (`product_id`) REFERENCES `tb_product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_review_user` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=383 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='鍟嗗搧璇勪环琛';
/*!40101 SET character_set_client = @saved_cs_client */;

