  KEY `idx_date_count` (`search_date`,`search_count` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='鎼滅储缁熻?琛';
