CREATE TABLE `tb_showcase_banner` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '灞曠ず鍐呭?ID',
  `placement` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '灞曠ず浣嶇疆锛欻OME_HERO銆丳ROMOTION_HERO銆丆ATEGORY_SPOTLIGHT',
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鏍囬?',
  `subtitle` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍓?爣棰',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '鎻忚堪',
  `badge_text` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '瑙掓爣鏂囨?',
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '涓诲浘璺?緞',
  `mobile_image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绉诲姩绔?富鍥捐矾寰',
  `button_text` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鎸夐挳鏂囨?',
  `link_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '閾炬帴绫诲瀷',
  `link_target` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '閾炬帴鐩?爣',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '鎺掑簭',
  `status` tinyint NOT NULL DEFAULT '1',
  `start_time` datetime DEFAULT NULL COMMENT '寮??鏃堕棿',
  `end_time` datetime DEFAULT NULL COMMENT '缁撴潫鏃堕棿',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_showcase_placement` (`placement`),
  KEY `idx_showcase_status` (`status`),
  KEY `idx_showcase_sort` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='灞曠ず鍐呭?琛';
