DROP TABLE IF EXISTS `tb_upload_file`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_upload_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鏂囦欢ID',
  `file_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鏂囦欢绫诲瀷锛欰VATAR-澶村儚锛孭RODUCT-鍟嗗搧锛孋ATEGORY-鍒嗙被锛孭ROMOTION-淇冮攢锛孯EVIEW-璇勪环',
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鏂囦欢璺?緞',
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍘熷?鏂囦欢鍚',
  `file_size` bigint DEFAULT NULL COMMENT '鏂囦欢澶у皬(瀛楄妭)',
  `user_id` bigint NOT NULL COMMENT '涓婁紶鐢ㄦ埛ID',
  `username` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '涓婁紶鐢ㄦ埛鍚',
  `status` tinyint NOT NULL DEFAULT '0',
  `reviewer_id` bigint DEFAULT NULL COMMENT '瀹℃牳浜篒D',
  `reviewer_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '瀹℃牳浜虹敤鎴峰悕',
  `review_time` datetime DEFAULT NULL COMMENT '瀹℃牳鏃堕棿',
  `review_remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '瀹℃牳澶囨敞',
  `related_id` bigint DEFAULT NULL COMMENT '鍏宠仈ID锛堝?鍟嗗搧ID锛',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '涓婁紶鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_upload_file_user` (`user_id`),
  KEY `idx_upload_file_status` (`status`),
  KEY `idx_upload_file_type` (`file_type`),
  CONSTRAINT `fk_upload_file_user` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='涓婁紶鏂囦欢琛';
