DROP TABLE IF EXISTS `tb_wishlist`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_wishlist` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `product_id` bigint NOT NULL COMMENT '鍟嗗搧ID',
  `added_price` decimal(10,2) DEFAULT NULL COMMENT '鍔犲叆鏃剁殑浠锋牸',
  `cooling_days` int DEFAULT '3' COMMENT '鍐烽潤鏈熷ぉ鏁',
  `cooling_end_time` datetime DEFAULT NULL COMMENT '鍐烽潤鏈熺粨鏉熸椂闂',
  `status` int DEFAULT NULL,
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍔犲叆鍘熷洜/澶囨敞',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_wishlist_user` (`user_id`),
  KEY `idx_wishlist_product` (`product_id`),
  KEY `idx_wishlist_status` (`status`),
  CONSTRAINT `fk_wishlist_product` FOREIGN KEY (`product_id`) REFERENCES `tb_product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_wishlist_user` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=207 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='鎯宠?娓呭崟琛';
